import {createGlove,GRIP} from './hands.js';
// Arm pose is applied after the authentic soldier animation, then restored
// before the next animation sample. The existing skeleton and weapons remain authoritative.
export function createShieldArm(T,{scene,camera,getModel=()=>null,getGame=()=>null,getWeapon=()=>null,getLeftController=()=>null,renderer}={}){
 const mats={fabric:new T.MeshStandardMaterial({color:0x111922,roughness:.9}),plate:new T.MeshStandardMaterial({color:0x34424c,roughness:.4,metalness:.65}),trim:new T.MeshStandardMaterial({color:0x7a8b98,roughness:.32,metalness:.75}),glow:new T.MeshBasicMaterial({color:0xff80b2,toneMapped:false}),accent:new T.MeshBasicMaterial({color:0xff80b2,toneMapped:false}),metal:new T.MeshStandardMaterial({color:0x73828f,metalness:.75,roughness:.35})};
 const owned=[],make=(g,m,parent,p=[0,0,0],r=[0,0,0])=>{owned.push(g);const mesh=new T.Mesh(g,m);mesh.position.set(...p);mesh.rotation.set(...r);parent.add(mesh);return mesh;};
 function projector(){const root=new T.Group();root.name='Projecteur du bras gauche';make(new T.CylinderGeometry(.076,.085,.056,8),mats.plate,root,[0,0,0],[Math.PI/2,0,0]);make(new T.CylinderGeometry(.052,.052,.008,20),mats.glow,root,[0,0,.032],[Math.PI/2,0,0]);make(new T.TorusGeometry(.064,.004,6,32),mats.trim,root,[0,0,.030]);make(new T.TorusGeometry(.045,.0035,6,24),mats.glow,root,[0,0,-.030]);make(new T.BoxGeometry(.045,.012,.005),mats.glow,root,[0,-.014,-.032]);return root;}
 const worldProjector=projector();scene.add(worldProjector);const fpsRoot=new T.Group();fpsRoot.name='Bras gauche / garde FPS';camera?.add(fpsRoot);const glove=createGlove(mats,{mirror:true,sleeve:true,arm:true});glove.position.set(-.30,-.26,-.57);glove.userData.setForearm?.([-.15,-.30,.36]);glove.userData.animate?.({grip:.70},.016,-1);fpsRoot.add(glove);const fpsProjector=projector();fpsProjector.position.set(-.27,-.20,-.61);fpsProjector.rotation.y=Math.PI;fpsRoot.add(fpsProjector);
 let bound=null,original=null,wrapper=null,backup=null,blend=0,colour=0xff80b2,hiddenWeapon=null;const point=new T.Vector3(),up=new T.Vector3(0,1,0);
 function orient(bone,child,target){bone.updateWorldMatrix(true,true);const origin=bone.getWorldPosition(new T.Vector3()),from=child.getWorldPosition(new T.Vector3()).sub(origin),to=target.clone().sub(origin);if(from.lengthSq()<1e-10||to.lengthSq()<1e-10)return;const world=bone.getWorldQuaternion(new T.Quaternion()),parent=bone.parent.getWorldQuaternion(new T.Quaternion()).invert();bone.quaternion.copy(parent.multiply(new T.Quaternion().setFromUnitVectors(from.normalize(),to.normalize()).multiply(world)));bone.updateWorldMatrix(false,true);}
 function solve(arm,target,pole){const {upper,fore,hand}=arm;upper.updateWorldMatrix(true,true);const s=upper.getWorldPosition(new T.Vector3()),k=fore.getWorldPosition(new T.Vector3()),w=hand.getWorldPosition(new T.Vector3()),a=s.distanceTo(k),b=k.distanceTo(w),dir=target.clone().sub(s),dist=Math.max(Math.abs(a-b)+.001,Math.min(a+b-.001,dir.length()));dir.normalize();const normal=pole.clone().sub(s).addScaledVector(dir,-pole.clone().sub(s).dot(dir)).normalize(),along=(a*a-b*b+dist*dist)/(2*dist),elbow=s.clone().addScaledVector(dir,along).addScaledVector(normal,Math.sqrt(Math.max(0,a*a-along*along)));orient(upper,fore,elbow);orient(fore,hand,s.clone().addScaledVector(dir,dist));}
 function restore(){if(!backup||!bound)return;const arm=bound.arms?.[0];arm?.upper.quaternion.copy(backup.upper);arm?.fore.quaternion.copy(backup.fore);if(bound.freeHand){bound.freeHand.visible=backup.freeVisible;bound.freeHand.position.copy(backup.freeP);bound.freeHand.quaternion.copy(backup.freeQ);}if(bound.gun?.userData.support)bound.gun.userData.support.visible=backup.supportVisible;backup=null;}
 function apply(){const g=getGame(),arm=bound?.arms?.[0],root=bound?.root;if(!g||!arm||blend<.005||g.weapon?.dual)return;backup={upper:arm.upper.quaternion.clone(),fore:arm.fore.quaternion.clone(),freeVisible:bound.freeHand?.visible,freeP:bound.freeHand?.position.clone()||new T.Vector3(),freeQ:bound.freeHand?.quaternion.clone()||new T.Quaternion(),supportVisible:bound.gun?.userData.support?.visible};
  const p=g.player,c=Math.cos(p.yaw||0),s=Math.sin(p.yaw||0),left=new T.Vector3(-c,0,s),front=new T.Vector3(-s,0,-c),base=new T.Vector3(p.x,(p.elevation||0)+(p.crouched?1.02:1.37),p.z),target=base.clone().addScaledVector(left,.30).addScaledVector(front,.37),pole=base.clone().addScaledVector(left,.55).addScaledVector(front,.08);pole.y-=.18;const current=arm.hand.getWorldPosition(new T.Vector3());target.lerpVectors(current,target,blend);solve(arm,target,pole);
  const rest=bound.freeHand;if(rest?.userData.rlh){rest.visible=true;root.updateMatrixWorld(true);rest.quaternion.copy(root.getWorldQuaternion(new T.Quaternion()).invert().multiply(arm.hand.getWorldQuaternion(new T.Quaternion())).multiply(rest.userData.rlh.quaternion.clone().invert()));const pos=root.worldToLocal(arm.hand.getWorldPosition(new T.Vector3())).sub(new T.Vector3(...GRIP.wrist).multiply(rest.scale).applyQuaternion(rest.quaternion));rest.userData.setBasePosition?.(pos.toArray());rest.userData.animate?.({grip:.7},.016,-1);}
  if(bound.gun?.userData.support)bound.gun.userData.support.visible=false;bound.actor?.skeleton.update();
 }
 function bind(model){if(model===bound)return;restore();if(bound&&bound.animate===wrapper)bound.animate=original;bound=model;original=null;wrapper=null;if(!model?.animate)return;original=model.animate;wrapper=function(...args){restore();const result=original.apply(model,args);apply();return result;};model.animate=wrapper;}
 function restoreWeapon(){if(hiddenWeapon?.userData.support)hiddenWeapon.userData.support.visible=!!hiddenWeapon.userData.showSupport&&!!hiddenWeapon.userData.supportPoint;hiddenWeapon=null;}
 return{update(game,dt,amount,frame){blend=amount;bind(getModel());const model=bound,xr=!!renderer?.xr?.isPresenting,firstPerson=!!camera&&!xr&&!model?.root.visible,active=amount>.01&&game.player.hp>0;worldProjector.visible=active&&(!firstPerson||game.weapon.dual);fpsRoot.visible=active&&firstPerson&&!game.weapon.dual;
   if(firstPerson&&active&&!game.weapon.dual){const gun=getWeapon();if(hiddenWeapon!==gun){restoreWeapon();hiddenWeapon=gun;}if(gun?.userData.support)gun.userData.support.visible=false;}else restoreWeapon();
   if(active&&firstPerson&&!game.weapon.dual){fpsRoot.position.y=-.32*(1-amount);fpsRoot.rotation.z=-.6*(1-amount);fpsRoot.updateWorldMatrix(true,true);fpsProjector.getWorldPosition(point);return point.clone();}
   if(active&&firstPerson&&game.weapon.dual){const hand=getWeapon()?.userData.support;if(hand){hand.updateWorldMatrix(true,false);point.set(...GRIP.wrist);hand.localToWorld(point);worldProjector.position.copy(point);hand.getWorldQuaternion(worldProjector.quaternion);worldProjector.rotateY(Math.PI);return point.clone();}}
   const tracked=xr&&getLeftController?.();if(active&&tracked){tracked.updateWorldMatrix(true,false);tracked.getWorldPosition(point);worldProjector.position.copy(point);tracked.getWorldQuaternion(worldProjector.quaternion);worldProjector.rotateY(Math.PI);return point.clone();}
   const hand=model?.arms?.[0]?.hand;if(active&&hand){hand.getWorldPosition(point);worldProjector.position.copy(point).addScaledVector(new T.Vector3(frame.forward.x,0,frame.forward.z),.04);worldProjector.rotation.set(0,Math.atan2(frame.forward.x,frame.forward.z),0);return worldProjector.position.clone();}
   point.set(game.player.x,frame.centre.y+.08,game.player.z).addScaledVector(new T.Vector3(frame.left.x,0,frame.left.z),.30).addScaledVector(new T.Vector3(frame.forward.x,0,frame.forward.z),.32);worldProjector.position.copy(point);worldProjector.rotation.set(0,Math.atan2(frame.forward.x,frame.forward.z),0);return point.clone();
  },setColour(hex){if(hex===colour)return;colour=hex;mats.glow.color.setHex(hex);mats.accent.color.setHex(hex);},dispose(){restore();restoreWeapon();if(bound?.animate===wrapper)bound.animate=original;worldProjector.removeFromParent();fpsRoot.removeFromParent();glove.userData.dispose?.();for(const g of owned)g.dispose();for(const m of Object.values(mats))m.dispose();}}
}
